class AsyncThePlaidApiClient(BaseThePlaidApiClient[AsyncRawClient]):
    def __init__(
        self,
        *,
        environment: Environment = "production",
        timeout: float = DEFAULT_TIMEOUT,
        server_config: ServerConfigOrDict | None = None,
        retry_options: int | RetryOptionsOrDict | None = None,
        custom_async_http_client: AsyncHttpClient | None = None,
        client_id: str | None = None,
        secret: str | None = None,
        plaid_version: str | None = None,
        oauth2: ClientCredentialsOrDict[Oauth2Scope] | None = None,
        oauth2_token_source: AsyncTokenSource[ClientCredentials[Oauth2Scope]] | None = None,
    ) -> None:
        super().__init__(
            environment=environment, timeout=timeout, server_config=server_config, retry_options=retry_options
        )
        self._raw_client = AsyncRawClient(
            http_client=(
                custom_async_http_client if custom_async_http_client is not None else AsyncHttpx2Client(timeout=timeout)
            ),
            retry_options=self._retry_options,
            global_headers=[
                param[str]("User-Agent", "ThePlaidApiClient/0.1.0 Python"),
                param[str]("X-APIMatic-Lang", "Python"),
                param[str]("X-APIMatic-Package-Version", "0.1.0"),
                param[str]("X-APIMatic-Gen-Version", "4.0.0"),
                param[str]("X-APIMatic-OS", OPERATING_SYSTEM),
                param[str]("X-APIMatic-Runtime", PYTHON_RUNTIME),
            ],
        )
        self._auth = AsyncAuthSchemes(
            client_id=ApiKeyHeaderScheme("PLAID-CLIENT-ID", client_id) if client_id is not None else no_auth,
            secret=ApiKeyHeaderScheme("PLAID-SECRET", secret) if secret is not None else no_auth,
            plaid_version=ApiKeyHeaderScheme("Plaid-Version", plaid_version) if plaid_version is not None else no_auth,
            oauth2=(
                AsyncOAuth2Scheme(
                    credentials=ClientCredentials[Oauth2Scope].coerce(oauth2),
                    source=(
                        oauth2_token_source
                        if oauth2_token_source is not None
                        else AsyncClientCredentialsTokenSource[Oauth2Scope](
                            client=self._raw_client,
                            token_url=self._server.access_token_server("/token"),
                            placement=client_secret_basic,
                        )
                    ),
                )
                if oauth2 is not None
                else no_auth
            ),
        )

    @cached_property
    def with_raw_response(self) -> AsyncApiWithRawResponse:
        return AsyncApiWithRawResponse(self._raw_client, self._server, self._auth)

    async def accounts_balance_get(
        self,
        body: AccountsBalanceGetRequest | AccountsBalanceGetRequestDict,
        *,
        request_options: RequestOptionsOrDict | None = None,
    ) -> AccountsGetResponse:
        """The ``/accounts/balance/get`` endpoint returns the real-time balance for each of an Item's accounts. While
        other endpoints, such as ``/accounts/get``, return a balance object, ``/accounts/balance/get`` forces the
        available and current balance fields to be refreshed rather than cached. This endpoint can be used for existing
        Items that were added via any of Plaid's other products. This endpoint can be used as long as Link has been
        initialized with any other product; ``balance`` itself is not a product that can be used to initialize Link. As
        this endpoint triggers a synchronous request for fresh data, latency may be higher than for other Plaid
        endpoints (typically less than 10 seconds, but occasionally up to 30 seconds or more); if you encounter errors,
        you may find it necessary to adjust your timeout period when making requests.

        Note: If you are getting real-time balance for the purpose of assessing the return risk of a proposed ACH
        transaction, it is recommended to use ``/signal/evaluate`` instead of ``/accounts/balance/get``.
        ``/signal/evaluate`` returns the same real-time balance information and also provides access to Signal Rules,
        which provides no-code transaction business logic configuration, backtesting and recommendations for tuning your
        transaction acceptance logic, and the ability to easily switch between Balance and Signal Transaction Scores as
        needed for ultra-low-latency, ML-powered risk assessments. For more details, see the `Balance documentation
        <https://plaid.com/docs/balance/#balance-integration-options>`__.

        Args:
            body: The request body.
            request_options: Per-call overrides for this one request, such as a timeout, extra headers, or its retry
                count and statuses.

        Returns:
            OK

        Raises:
            ApiError: If the API responds with an error status code. ``error`` is ``RawError``."""
        return unwrap(await self.with_raw_response.accounts_balance_get(body, request_options=request_options))

    async def accounts_get(
        self, body: AccountsGetRequest | AccountsGetRequestDict, *, request_options: RequestOptionsOrDict | None = None
    ) -> AccountsGetResponse:
        """The ``/accounts/get`` endpoint can be used to retrieve a list of accounts associated with any linked Item.
        Plaid will only return active bank accounts -- that is, accounts that are not closed and are capable of carrying
        a balance. To return new accounts that were created after the user linked their Item, you can listen for the
        https://plaid.com/docs/api/items/#new_accounts_available webhook and then use Link's `update mode
        <https://plaid.com/docs/link/update-mode/>`__ to request that the user share this new account with you.

        ``/accounts/get`` is free to use and retrieves cached information, rather than extracting fresh information from
        the institution. The balance returned will reflect the balance at the time of the last successful Item update.
        If the Item is enabled for a regularly updating product, such as Transactions, Investments, or Liabilities, the
        balance will typically update about once a day, as long as the Item is healthy. If the Item is enabled only for
        products that do not frequently update, such as Auth or Identity, balance data may be much older.

        For real-time balance information, use the paid endpoints ``/accounts/balance/get`` or ``/signal/evaluate``
        instead.

        Args:
            body: The request body.
            request_options: Per-call overrides for this one request, such as a timeout, extra headers, or its retry
                count and statuses.

        Returns:
            success

        Raises:
            ApiError: If the API responds with an error status code. ``error`` is ``RawError``."""
        return unwrap(await self.with_raw_response.accounts_get(body, request_options=request_options))

